import { describe, expect, it, vi } from "vitest";

const vscodeMock = vi.hoisted(() => {
  class TreeItem {
    description?: string;
    tooltip?: string;
    contextValue?: string;
    iconPath?: unknown;

    constructor(
      readonly label: string,
      readonly collapsibleState: number
    ) {}
  }

  class ThemeIcon {
    constructor(readonly id: string) {}
  }

  class EventEmitter {
    readonly event = vi.fn();
    readonly fire = vi.fn();
  }

  return {
    TreeItem,
    ThemeIcon,
    EventEmitter,
    TreeItemCollapsibleState: { None: 0, Collapsed: 1, Expanded: 2 },
  };
});

vi.mock("vscode", () => vscodeMock);

import { BoardFinding } from "./fleet";
import { DoctorNode, DoctorViewProvider } from "./doctorViewProvider";

function finding(overrides: Partial<BoardFinding> = {}): BoardFinding {
  return {
    ailment: "duplicate_title",
    subject: "Implement auth flow",
    remedy: "one goal, one title, more than one live task: decide which is the work",
    task_ids: ["task:1", "task:2"],
    ...overrides,
  };
}

describe("DoctorViewProvider", () => {
  it("starts empty until updated", () => {
    const provider = new DoctorViewProvider();

    expect(provider.getChildren()).toEqual([]);
    expect(provider.findingCount).toBe(0);
  });

  it("groups findings by ailment as top-level nodes", () => {
    const provider = new DoctorViewProvider();
    provider.update([
      {
        ailment: "blocked_without_gate",
        label: "Blocked with no gate",
        findings: [finding({ ailment: "blocked_without_gate", subject: "Fix deploy script" })],
      },
      {
        ailment: "duplicate_title",
        label: "Duplicate title",
        findings: [finding(), finding({ subject: "Implement auth flow" })],
      },
    ]);

    const groups = provider.getChildren();

    expect(groups).toHaveLength(2);
    expect(groups.map((node) => (node as { group: { label: string } }).group.label)).toEqual([
      "Blocked with no gate",
      "Duplicate title",
    ]);
    expect(provider.findingCount).toBe(3);
  });

  it("renders a group node with its finding count and expands by default", () => {
    const provider = new DoctorViewProvider();
    provider.update([
      { ailment: "duplicate_title", label: "Duplicate title", findings: [finding(), finding()] },
    ]);
    const [group] = provider.getChildren();

    const item = provider.getTreeItem(group);

    expect(item.label).toBe("Duplicate title");
    expect(item.description).toBe("2 findings");
    expect(item.contextValue).toBe("doctor.group");
  });

  it("renders a finding node with its subject, task count, and remedy as the tooltip", () => {
    const provider = new DoctorViewProvider();
    provider.update([
      {
        ailment: "duplicate_title",
        label: "Duplicate title",
        findings: [finding({ subject: "Implement auth flow", task_ids: ["task:1", "task:2"] })],
      },
    ]);
    const [group] = provider.getChildren();
    const [findingNode] = provider.getChildren(group);

    const item = provider.getTreeItem(findingNode);

    expect(item.label).toBe("Implement auth flow");
    expect(item.description).toBe("2 tasks");
    expect(item.tooltip).toBe(
      "one goal, one title, more than one live task: decide which is the work"
    );
    expect(item.contextValue).toBe("doctor.finding");
  });

  it("falls back to the first task id when a finding has no subject", () => {
    const provider = new DoctorViewProvider();
    provider.update([
      {
        ailment: "blocked_without_gate",
        label: "Blocked with no gate",
        findings: [finding({ subject: null, task_ids: ["task:9"] })],
      },
    ]);
    const [group] = provider.getChildren();
    const [findingNode] = provider.getChildren(group);

    expect(provider.getTreeItem(findingNode).label).toBe("task:9");
  });

  it("leaves description and tooltip unset for a singular task with no remedy", () => {
    const provider = new DoctorViewProvider();
    provider.update([
      {
        ailment: "blocked_without_gate",
        label: "Blocked with no gate",
        findings: [finding({ remedy: null, task_ids: ["task:1"] })],
      },
    ]);
    const [group] = provider.getChildren();
    const [findingNode] = provider.getChildren(group);

    const item = provider.getTreeItem(findingNode);

    expect(item.description).toBe("1 task");
    expect(item.tooltip).toBeUndefined();
  });

  it("returns no children for a leaf finding node", () => {
    const provider = new DoctorViewProvider();
    provider.update([
      { ailment: "duplicate_title", label: "Duplicate title", findings: [finding()] },
    ]);
    const [group] = provider.getChildren();
    const [findingNode] = provider.getChildren(group);

    expect(provider.getChildren(findingNode as DoctorNode)).toEqual([]);
  });

  it("replaces the whole tree and fires a change event on update", () => {
    const provider = new DoctorViewProvider();
    provider.update([
      { ailment: "duplicate_title", label: "Duplicate title", findings: [finding()] },
    ]);

    provider.update([]);

    expect(provider.getChildren()).toEqual([]);
    expect(provider.findingCount).toBe(0);
  });

  it("tolerates a non-array update rather than throwing", () => {
    const provider = new DoctorViewProvider();

    provider.update(undefined as unknown as never);

    expect(provider.getChildren()).toEqual([]);
  });
});
